CREATE TABLE hosts(id TEXT PRIMARY KEY, name TEXT NOT NULL, document TEXT NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY, host_id TEXT NOT NULL REFERENCES hosts(id), mode TEXT NOT NULL, started_ms INTEGER NOT NULL, completed_ms INTEGER, document TEXT NOT NULL);
CREATE TABLE events(id TEXT PRIMARY KEY, host_id TEXT NOT NULL REFERENCES hosts(id), session_id TEXT NOT NULL REFERENCES sessions(id), sequence INTEGER NOT NULL, event_type TEXT NOT NULL, source TEXT NOT NULL, timestamp_ms INTEGER NOT NULL, actor_pid INTEGER, related_pid INTEGER, dedup_key TEXT NOT NULL UNIQUE, document TEXT NOT NULL);
CREATE INDEX events_time ON events(timestamp_ms);
CREATE INDEX events_host_type_time ON events(host_id,event_type,timestamp_ms);
CREATE INDEX events_related_pid ON events(host_id,related_pid,timestamp_ms);
CREATE TABLE event_provenance(event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, source TEXT NOT NULL, source_record_id TEXT NOT NULL, document TEXT NOT NULL, PRIMARY KEY(event_id,source,source_record_id));
CREATE TABLE processes(id TEXT PRIMARY KEY, host_id TEXT NOT NULL REFERENCES hosts(id), pid INTEGER NOT NULL, created_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, host_id TEXT NOT NULL REFERENCES hosts(id), path TEXT NOT NULL, updated_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE incidents(id TEXT PRIMARY KEY, host_id TEXT NOT NULL REFERENCES hosts(id), session_id TEXT NOT NULL REFERENCES sessions(id), status TEXT NOT NULL, severity TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), updated_ms INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1, document TEXT NOT NULL);
CREATE INDEX incidents_host_status ON incidents(host_id,status,updated_ms);
CREATE TABLE incident_events(incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, PRIMARY KEY(incident_id,event_id));
CREATE TABLE incident_edges(id INTEGER PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, document TEXT NOT NULL);
CREATE TABLE rule_matches(id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, document TEXT NOT NULL);
CREATE TABLE analyst_notes(id INTEGER PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, author TEXT NOT NULL, created_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE baselines(id TEXT PRIMARY KEY, updated_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE health(id TEXT PRIMARY KEY, updated_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE log_bookmarks(id TEXT PRIMARY KEY, updated_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE ti_cache(id TEXT PRIMARY KEY, updated_ms INTEGER NOT NULL, expires_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE config_audit(id INTEGER PRIMARY KEY, author TEXT NOT NULL, created_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE settings(id TEXT PRIMARY KEY, updated_ms INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE remote_spool(id INTEGER PRIMARY KEY AUTOINCREMENT, agent_id TEXT NOT NULL, session_id TEXT NOT NULL, sequence INTEGER NOT NULL, created_ms INTEGER NOT NULL, document TEXT NOT NULL, UNIQUE(agent_id,session_id,sequence));
CREATE TABLE migration_history(version INTEGER PRIMARY KEY, applied_ms INTEGER NOT NULL);
